def csv_rows(text):
    """
    Parse RFC 4180 CSV text and return a list of rows, each a list of string fields.
    Handles quoted fields containing commas and newlines, doubled quotes as escaped quotes,
    and CRLF or LF line endings.
    """
    rows = []
    fields = []
    i = 0
    n = len(text)

    while i < n:
        # Check if we're at the start of a field
        if i < n and text[i] == '"':
            # Quoted field
            i += 1  # skip opening quote
            field = []
            while i < n:
                if text[i] == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        # Doubled quote - escaped quote
                        field.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    field.append(text[i])
                    i += 1
            fields.append(''.join(field))

            # After a quoted field, we expect either a comma, a line ending, or end of input
            if i < n and text[i] == ',':
                i += 1
            elif i < n and text[i] == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    i += 2
                else:
                    i += 1
                rows.append(fields)
                fields = []
            elif i < n and text[i] == '\n':
                i += 1
                rows.append(fields)
                fields = []
            else:
                # End of input
                rows.append(fields)
                fields = []
                break
        else:
            # Unquoted field
            field = []
            while i < n:
                if text[i] == ',':
                    i += 1
                    break
                elif text[i] == '\r':
                    if i + 1 < n and text[i + 1] == '\n':
                        i += 2
                    else:
                        i += 1
                    break
                elif text[i] == '\n':
                    i += 1
                    break
                else:
                    field.append(text[i])
                    i += 1
            fields.append(''.join(field))

            # After an unquoted field, check if we've hit a line ending
            if i < n and text[i] == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    i += 2
                else:
                    i += 1
                rows.append(fields)
                fields = []
            elif i < n and text[i] == '\n':
                i += 1
                rows.append(fields)
                fields = []
            else:
                # End of input
                rows.append(fields)
                fields = []
                break

    return rows
